use genewars_runtime::{actor_activation::TrigTables,turret_projectile::{plan_turret_projectile_factory,plan_projectile_lifetime_prefix}};
use std::{fs,path::Path};
fn main(){let p=std::env::args().nth(1).unwrap();let p=Path::new(&p);let trig=TrigTables::generate_pinned().unwrap();let sin=trig.sine().try_into().unwrap();let cos=trig.cosine().try_into().unwrap();let mut out=Vec::new();
 for r in fs::read(p.join("factory-input.bin")).unwrap().chunks_exact(104){let mut pool=[[0;81];200];let slot=u16::from_le_bytes(r[81..83].try_into().unwrap())as usize;for a in &mut pool[..slot]{a[6]=5}pool[slot]=r[..81].try_into().unwrap();let at=[i16::from_le_bytes(r[83..85].try_into().unwrap()),i16::from_le_bytes(r[85..87].try_into().unwrap())];let ground=i32::from_le_bytes(r[87..91].try_into().unwrap());let height=i32::from_le_bytes(r[91..95].try_into().unwrap());let owner=r[95];let angles=std::array::from_fn(|i|u16::from_le_bytes(r[96+i*2..98+i*2].try_into().unwrap()));let shooter=i16::from_le_bytes(r[102..104].try_into().unwrap());let got=plan_turret_projectile_factory(&pool,slot as i16,owner,at,ground,0,height,angles,shooter,None,sin,cos).unwrap();out.extend(got.after_nonpointer)}
 fs::write(p.join("factory-actual.bin"),out).unwrap();let mut out=Vec::new();for r in fs::read(p.join("update-input.bin")).unwrap().chunks_exact(81){let before=r.try_into().unwrap();let plan=plan_projectile_lifetime_prefix(before).unwrap();out.extend(plan.after);out.extend([plan.retirement_required as u8,plan.near_query_required as u8]);}fs::write(p.join("update-actual.bin"),out).unwrap();println!("64 factories and240 postphysics prefixes");}
